#!/usr/bin/env bash
set -euo pipefail
target="$(printf %s 'c3JjL3Rlc3QvamF2YS9pby9yZWFjdGl2ZXgvcnhqYXZhMy9jb3JlL1JldHJ5LmphdmE=' | base64 -d)"
injection_type="$(printf %s 'YXBwZW5k' | base64 -d)"
match_pattern="$(printf %s '' | base64 -d)"
payload_file="$(mktemp)"
tmp_file="$(mktemp)"
cleanup() { rm -f "$payload_file" "$tmp_file"; }
trap cleanup EXIT
base64 -d > "$payload_file" <<'PAYLOAD_B64'

PAYLOAD_B64
case "$injection_type" in
  append)
    printf '\n' >> "$target"
    cat "$payload_file" >> "$target"
    printf '\n' >> "$target"
    ;;
  insert_before_match)
    awk -v pat="$match_pattern" -v pf="$payload_file" '
      BEGIN { inserted=0 }
      !inserted && index($0, pat) { while ((getline line < pf) > 0) print line; close(pf); inserted=1 }
      { print }
      END { if (!inserted) exit 42 }
    ' "$target" > "$tmp_file"
    mv "$tmp_file" "$target"
    ;;
  insert_after_match)
    awk -v pat="$match_pattern" -v pf="$payload_file" '
      BEGIN { inserted=0 }
      { print }
      !inserted && index($0, pat) { while ((getline line < pf) > 0) print line; close(pf); inserted=1 }
      END { if (!inserted) exit 42 }
    ' "$target" > "$tmp_file"
    mv "$tmp_file" "$target"
    ;;
  *)
    echo "unsupported injection_type: $injection_type" >&2
    exit 2
    ;;
esac

