+	}
+	cs_option(handle, CS_OPT_DETAIL, CS_OPT_DETAIL_REAL | CS_OPT_ON);
+
+	bool success[10];
+	memset(success, true, sizeof(success));
+
+	// addi a0, a1, 10 -> 0x00a58513
+	printf("Test 0: Testing addi a0, a1, 10\n");
